/**
 * Shader de la brume basse.
 *
 * ## L'idee mathematique
 *
 * Deux nappes de brume, chacune un bruit fractal etire en largeur : dense au
 * bas du cadre, dissoute au-dessus d'une crete que le bruit dessine. Les deux
 * plans glissent en sens contraires — c'est la parallaxe qui les separe a
 * l'oeil, plus surement que leur teinte. Le plan lointain monte plus haut
 * et porte une teinte froide ; le proche reste bas, plus dense, dans le
 * neutre du theme.
 *
 * La brume se pose par melange borne vers ses teintes : sur un fond clair,
 * elle grise ; sur un fond sombre, elle eclaircit. Dans les deux cas, elle
 * reste une brume et le texte reste lisible.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond.
 * - `uColorB` — la nappe proche.
 * - `uColorC` — la nappe lointaine.
 * - `uSpeed` — vitesse de glissement.
 * - `uHeight` — hauteur de la brume, en fraction du cadre.
 * - `uDensity` — opacite maximale des nappes.
 * - `uOctaves` — detail du bruit, et donc son cout.
 */
export const FOG_DRIFT_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uHeight;
uniform float uDensity;
uniform float uOctaves;

float brumeHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float brumeNoise(vec2 p) {
  vec2 cell = floor(p);
  vec2 local = fract(p);
  vec2 smoothed = local * local * (3.0 - 2.0 * local);

  float a = brumeHash(cell);
  float b = brumeHash(cell + vec2(1.0, 0.0));
  float c = brumeHash(cell + vec2(0.0, 1.0));
  float d = brumeHash(cell + vec2(1.0, 1.0));

  return mix(mix(a, b, smoothed.x), mix(c, d, smoothed.x), smoothed.y);
}

float brumeFbm(vec2 p, int octaves) {
  float total = 0.0;
  float amplitude = 0.5;
  float normalisation = 0.0;

  for (int i = 0; i < 5; i += 1) {
    if (i >= octaves) break;
    total += brumeNoise(p) * amplitude;
    normalisation += amplitude;
    p = p * 2.1 + vec2(3.7, 1.3);
    amplitude *= 0.5;
  }

  return total / max(normalisation, 0.0001);
}

// Une nappe : dense au bas, dissoute au-dessus d'une crete bruitee. Le bruit
// est etire en largeur — une brume s'etale, elle ne monte pas en colonnes.
float brumeNappe(vec2 p, float t, float vitesse, float hauteur, float echelle, int octaves, float graine) {
  vec2 q = vec2(p.x * echelle + t * vitesse, p.y * echelle * 2.2 + graine);
  float n = brumeFbm(q, octaves);

  float crete = max(hauteur, 0.02) * (0.5 + 0.9 * n);
  float masse = 1.0 - smoothstep(crete * 0.25, crete, p.y);

  return masse * (0.6 + 0.4 * n);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vec2(vUv.x * aspect, vUv.y);
  float t = uTime * uSpeed;
  int octaves = int(clamp(uOctaves, 1.0, 5.0));
  float densite = clamp(uDensity, 0.0, 1.0);

  // Le lointain monte plus haut, plus fin et plus lent ; le proche, bas et
  // large, glisse en sens contraire.
  float loin = brumeNappe(p, t, 0.12, uHeight * 1.35, 1.7, octaves, 3.7);
  float pres = brumeNappe(p, t, -0.2, uHeight * 0.85, 2.6, octaves, 9.1);

  // Les bornes gardent l'encre lisible : meme a pleine densite, la nappe
  // proche ne prend que les trois quarts de sa teinte.
  vec3 colour = mix(uColorA, uColorC, clamp(loin, 0.0, 1.0) * 0.55 * densite);
  colour = mix(colour, uColorB, clamp(pres, 0.0, 1.0) * 0.75 * densite);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Brume basse : deux nappes qui glissent en sens contraires au bas du cadre.
 *
 * ## Le principe
 *
 * Chaque nappe est un bruit fractal etire en largeur, dense au bas et
 * dissoute au-dessus d'une crete que le bruit dessine. Le plan lointain
 * monte plus haut, froid et fin ; le proche reste bas, dense, dans le neutre
 * du theme. Leur parallaxe fait la profondeur. Distinct de la fumee, qui
 * monte en volutes : ici la brume s'etale et reste au sol.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface et sous
 * mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { FOG_DRIFT_FRAGMENT } from './fog-drift.shader.js'

/** Ce que l'echappatoire recoit. */
export interface FogDriftControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface FogDriftOwnProps {
  /** Vitesse de glissement. @defaultValue 0.5 */
  speed?: number
  /** Hauteur de la brume, en fraction du cadre. @defaultValue 0.45 */
  height?: number
  /** Opacite maximale des nappes. @defaultValue 0.8 */
  density?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<FogDriftControls>
}

/** Toutes les proprietes. */
export type FogDriftProps = Customisable<FogDriftOwnProps>

/**
 * Tokens employes par defaut : le fond, la nappe proche, la nappe lointaine.
 *
 * Le neutre du theme fait la nappe proche : il grise un fond clair et
 * eclaircit un fond sombre, ce qui est exactement ce qu'une brume fait.
 */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-theme-muted',
  '--o-palette-sky-300',
] as const

/** Repli par defaut : un degrade fige, dans les memes tons. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-t o-from-zinc-200 dark:o-from-zinc-800 o-to-zinc-50 dark:o-to-zinc-950'

/**
 * Detail du bruit hors qualite basse.
 *
 * Deux nappes, une somme d'octaves chacune : chaque octave se paie deux
 * fois. C'est le seul levier de cout du shader.
 */
const OCTAVES = 4

/** Detail du bruit en qualite basse. */
const LOW_OCTAVES = 2

/**
 * Brume basse.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <FogDrift className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function FogDrift({
  speed = 0.5,
  height = 0.45,
  density = 0.8,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: FogDriftProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: FOG_DRIFT_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uHeight: height, uDensity: density, uOctaves: OCTAVES },
    name: 'fog-drift',
    degrade: (quality) => ({
      uOctaves: quality === 'low' ? LOW_OCTAVES : OCTAVES,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
